# typed: strict
# frozen_string_literal: true

return unless defined?(ActiveRecord::Base)

require 'tapioca/dsl/compilers/active_record_relations'

module Tapioca
  module Dsl
    module Compilers
      # Adds `with_ordinality` to the relations generated by the ActiveRecordRelations compiler,
      # for models extended by ActiveRecord::WithOrdinality.
      # (The `in_order_of` override needs no signature, since the generated one is untyped.)
      # Compilers decorate a constant in order of their names, so this runs after ActiveRecordRelations.
      #
      #: [ConstantType = singleton(::ActiveRecord::Base)]
      class ActiveRecordWithOrdinality < Compiler
        include Helpers::ActiveRecordConstantsHelper

        # @override
        #: -> void
        def decorate
          return unless compiler_enabled?('ActiveRecordRelations')

          root.create_path(constant) do |model|
            model.create_module(RelationMethodsModuleName) do |mod|
              create_with_ordinality_method(mod, RelationClassName)
            end

            model.create_module(AssociationRelationMethodsModuleName) do |mod|
              create_with_ordinality_method(mod, AssociationRelationClassName)
            end
          end
        end

        class << self
          # @override
          #: -> Enumerable[Module[top]]
          def gather_constants
            ActiveRecordRelations.gather_constants.grep(::ActiveRecord::WithOrdinality)
          end
        end

      private

        #: (RBI::Scope scope, String return_type) -> void
        def create_with_ordinality_method(scope, return_type)
          scope.create_method(
            'with_ordinality',
            parameters: [
              create_param('column_names', type: 'T.any(Symbol, String, T::Array[T.any(Symbol, String)])'),
              create_param('values', type: 'T::Enumerable[T.untyped]'),
              create_kw_opt_param('as', type: 'T.nilable(T.any(Symbol, String))', default: 'nil'),
              create_kw_opt_param('filter', type: 'T::Boolean', default: 'true'),
              create_kw_opt_param('join_table_name', type: 'T.nilable(T.any(Symbol, String))', default: 'nil'),
            ],
            return_type:
          )
        end
      end
    end
  end
end
